const terms = query => [...new Set(norm(query).split(" ").filter(t => t.length >= 2 && !["a","an","and","for","from","in","of","on","or","the","to","with"].includes(t)))].slice(0, 24);
const itemText = item => norm([item.slug,item.title,item.description,item.category,(item.tags||[]).join(" "),item.keywords,item.launch_story].join(" "));
const publicItem = item => ({ kind:item.kind, slug:item.slug, title:item.title, description:item.description, category:item.category, tags:item.tags, install_command:item.install_command, github_url:item.github_url, website_url:item.website_url, scope_note:item.scope_note, version:item.version, last_updated:item.last_updated, source_path:item.source_path, provenance:"Reviewed committed Kujolang.ai content" });
